#!/usr/bin/env python3 # -*- coding: utf-8 -*- """ 自定义 Base8 解码器（纯解码，不再尝试 base64） 支持： - 自定义 8 字符映射集 - 忽略填充字符（默认 '='） """ import argparse import sys def base8_decode(encoded: str, charset: str, pad_char: str = '=') -> bytes: if len(charset) != 8: raise ValueError("映射字符集长度必须为 8 个字符。") if len(set(charset)) != 8: raise ValueError("映射字符集中含重复字符，请确保 8 个字符互不相同。") mapping = {ch: i for i, ch in enumerate(charset)} # 去除空白和填充字符 cleaned = "".join(ch for ch in encoded if not ch.isspace() and ch != pad_char) # 将每个符号映射为 3 位二进制并拼接 bits = [] for ch in cleaned: if ch not in mapping: raise ValueError(f"遇到未知字符: {ch!r}（不在映射字符集中）。") bits.append(f"{mapping[ch]:03b}") bitstr = "".join(bits) # 每 8 位组成一个字节（丢弃尾端不足 8 位的） out = bytearray() for i in range(0, (len(bitstr) // 8) * 8, 8): out.append(int(bitstr[i:i+8], 2)) return bytes(out) def main(): parser = argparse.ArgumentParser(description="自定义 Base8 解码器（纯解码版）") parser.add_argument('-m', '--mapping', help="8 字符映射集，例如: ?CTFmisc") parser.add_argument('-s', '--string', help="直接传入密文字符串") parser.add_argument('-f', '--file', help="从文件读取密文") parser.add_argument('-p', '--pad', default='=', help="填充字符（默认 '='）") args = parser.parse_args() mapping = args.mapping or input("请输入映射字符集（8 个字符）: ").strip() if not args.string and not args.file: encoded = input("请输入密文（可以包含填充 '='+）: ").strip() elif args.file: with open(args.file, 'r', encoding='utf-8') as f: encoded = f.read() else: encoded = args.string try: decoded = base8_decode(encoded, mapping, pad_char=args.pad) except Exception as e: print("解码失败:", e, file=sys.stderr) sys.exit(1) print("解码后 bytes (hex):", decoded.hex()) try: print("解码后 (utf-8):", decoded.decode('utf-8')) except Exception: print("解码后 (utf-8, replace):", decoded.decode('utf-8', errors='replace')) if __name__ == '__main__': main() 解得ZmxhZ3tUaDNfUHIxbmMxcGwzXzBmX0Jhc2VfMXNfUzBfRXp6fQ==，base64解码
